local s_vsh = [[
attribute vec2 vPosition;
varying vec2 vUV0;
void main()
{
    gl_Position = vec4(vPosition, 0.0, 1.0);
    //An opportunism code. Do not use it unless you know what it means.
    vUV0 = (vPosition.xy + 1.0) / 2.0;
}
]]

local s_fsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

    uniform sampler2D inputImageTexture;
    uniform vec2  uMainTexSize;

    uniform int uColorModel;
    uniform int uPattern;
    uniform float uPeriod;
    uniform float uAngle;
    uniform int uAnti_alias;
    uniform float uTurbulence;
    uniform float uBlocksize;
    uniform float uAngleBoost;

    varying vec2 vUV0;
    
    float spachrotyze(float x,
        float y,
        float part_white,
        float offset,
        float hue,
        int   pattern,
        float period,
        float turbulence,
        float blocksize,
        float angleboost,
        float angle,
        int   max_aa_samples)
    {
        float acc = 0.0;
        float twist = 3.1415 / 2. - ((hue * angleboost) + angle);
        float width  = (period * (1.0 - turbulence) + (period * offset) * turbulence);
        float vec0 = cos(twist);
        float vec1 = sin(twist);

        float xi = 0.5;
        float yi = 0.2;
        int count = 0;
        int inn = 0;
        float old_acc = 0.0;

        x =x+ period * 2.0;
        y =y+ period * 2.0;

        for (int i = 0; i < max_aa_samples ; i++)
        {
            xi = mod (xi + 0.61803, 1.0);
            yi = mod (yi + (0.61803/1.61235), 1.0);

            old_acc = acc;

            float u = mod (x + xi - 0.5 * width, blocksize * width);
            float v = mod (y + yi - 0.5 * width, blocksize * width);

            float w = vec0 * u + vec1 * v;
            float q = vec1 * u - vec0 * v;

            float wperiod = mod (w, width);
            float wphase  = (wperiod / width) * 2.0 - 1.0;

            float qperiod = mod (q, width);
            float qphase  = (qperiod / width) * 2.0 - 1.0;

            if (pattern == 1)       /* line */
            {
                if (abs (wphase) < part_white)
                inn ++;
            }
            else if (pattern == 2) /* dot */
            {
                if (qphase * qphase + wphase * wphase <
                part_white * part_white * 2.0)
                inn ++;
            }
            else if (pattern == 3) /* diamond */
            {
                if ((abs (wphase) + abs (qphase))/2.0 < part_white )
                inn++;
            }
            count ++;

            acc = float(inn) / float(count);
            if (i > 3 && abs (acc - old_acc) < 0.23)
                break;
            old_acc = acc;
        }
        return acc;
    }
    
    
    void main()
    {
        vec4 color = texture2D(inputImageTexture, vUV0);

        float luminance=color.g;
        float chroma=abs(color.r-color.g);
        float Angle=abs(color.b-color.g);

        float blocksize=uBlocksize;
        if (blocksize < 0.0)
            blocksize = 819200.0;
        
        if (uColorModel==1)
        {
            float gray=spachrotyze(vUV0.x*uMainTexSize.x,vUV0.y*uMainTexSize.y,luminance,chroma,Angle,uPattern,
                        uPeriod/2.0,uTurbulence,blocksize,uAngleBoost,radians(uAngle),uAnti_alias);
            
            gl_FragColor = vec4(gray,gray,gray,1.0);
        }
        
        if (uColorModel==2)
        {
            float gray=1.0-spachrotyze(vUV0.x*uMainTexSize.x,vUV0.y*uMainTexSize.y,1.0-luminance,chroma,Angle,uPattern,
                        uPeriod/2.0,uTurbulence,blocksize,uAngleBoost,radians(uAngle),uAnti_alias);
            
            gl_FragColor = vec4(gray,gray,gray,1.0);
        }
    }
]]

