function Newsprint:updateValue(index, val1, val2, val3)
    self.program:bind()
    if index == 1 then
        --pattern
        -- white on black  <--->  1
        -- black on white  <--->  2
        self.program:sendUniformi("uColorModel", val1)
    elseif index == 2 then
        --pattern
        -- Line  <--->  1
        -- Circle <--->  2
        -- Diamond <--->  3
        self.program:sendUniformi("uPattern", val1)
    elseif index == 3 then
        --period
        self.program:sendUniformf("uPeriod", val1)
    elseif index == 4 then
        --angle
        self.program:sendUniformf("uAngle", val1)
    elseif index == 5 then
        --Anti_alias
        self.program:sendUniformi("uAnti_alias", val1)
    elseif index == 6 then
        --turbulence
        self.program:sendUniformf("uTurbulence", val1)
    elseif index == 7 then
        --blocksize
        self.program:sendUniformf("uBlocksize", val1)
    elseif index == 8 then
        --angleboost
        self.program:sendUniformf("uAngleBoost", val1)
    end
end

function Newsprint:resize(width, height)
    self.program:bind()
    self.program:sendUniformf("uMainTexSize", width, height)
end

function Newsprint:render(outFBO, inputTex)
